import { authenticate } from "../shopify.server";
import { supabase } from "../services/supabase.server";
import {
  getClientIp,
  getLocationFromIp,
} from "../services/geo.server";

/**
 * Analytics events generated by the NearbyPulse widget itself.
 *
 * These events are different from storefront activity events such as:
 * - product_viewed
 * - add_to_cart
 * - checkout_started
 * - order_completed
 */
const ALLOWED_ANALYTICS_EVENT_TYPES = new Set([
  "widget_shown",
  "widget_clicked",
  "add_to_cart",
]);

/**
 * Genuine storefront activities that may support a social-proof message.
 */
const ALLOWED_ACTIVITY_EVENT_TYPES = [
  "order_completed",
  "checkout_started",
  "add_to_cart",
  "product_viewed",
];

/**
 * Higher-value activity is preferred when multiple recent activities exist.
 */
const ACTIVITY_PRIORITY = {
  order_completed: 100,
  checkout_started: 80,
  add_to_cart: 60,
  product_viewed: 40,
};

/**
 * Default templates are only used when the merchant has not created
 * templates for the selected activity type.
 */
const DEFAULT_TEMPLATES = {
  order_completed: [
    "Someone from {city} purchased {product} {time} ago.",
    "A customer near {city} ordered {product} {time} ago.",
    "{product} was purchased near {city} {time} ago.",
  ],

  checkout_started: [
    "A shopper near {city} started checkout with {product} {time} ago.",
    "Someone near {city} recently started checkout with {product}.",
  ],

  add_to_cart: [
    "A shopper near {city} added {product} to their cart {time} ago.",
    "Someone in {city} recently added {product} to their cart.",
  ],

  product_viewed: [
    "Someone near {city} viewed {product} {time} ago.",
    "{product} recently received attention near {city}.",
  ],
};

const DEFAULT_RESPONSE = {
  shouldShow: false,
  message: null,
};

/**
 * Safely cleans a string before it is returned or saved.
 */
function cleanString(value, maximumLength = 255) {
  if (typeof value !== "string") {
    return null;
  }

  const cleaned = value.trim();

  if (!cleaned) {
    return null;
  }

  return cleaned.slice(0, maximumLength);
}

/**
 * Converts a value to a finite number.
 */
function toFiniteNumber(value) {
  const number = Number(value);

  return Number.isFinite(number) ? number : null;
}

/**
 * Keeps a number within a safe range.
 */
function clampNumber(value, minimum, maximum, fallback) {
  const parsed = Number(value);

  if (!Number.isFinite(parsed)) {
    return fallback;
  }

  return Math.max(minimum, Math.min(parsed, maximum));
}

/**
 * Returns a random item from an array.
 */
function getRandomItem(items) {
  if (!Array.isArray(items) || items.length === 0) {
    return null;
  }

  return items[Math.floor(Math.random() * items.length)];
}

/**
 * Accepts either a numeric Shopify product ID or a Shopify GID.
 *
 * Examples:
 * 123456789
 * gid://shopify/Product/123456789
 */
function normaliseProductId(value) {
  if (value === null || value === undefined) {
    return null;
  }

  const productId = String(value).trim();

  if (!productId) {
    return null;
  }

  return productId.replace(
    "gid://shopify/Product/",
    "",
  );
}

/**
 * Returns a readable elapsed-time value.
 *
 * Examples:
 * 1 minute
 * 12 minutes
 * 3 hours
 * 1 day
 */
function formatTimeSince(createdAt) {
  const createdTimestamp = new Date(createdAt).getTime();

  if (!Number.isFinite(createdTimestamp)) {
    return "recently";
  }

  const differenceMilliseconds = Math.max(
    0,
    Date.now() - createdTimestamp,
  );

  const differenceMinutes = Math.floor(
    differenceMilliseconds / 60000,
  );

  if (differenceMinutes < 2) {
    return "1 minute";
  }

  if (differenceMinutes < 60) {
    return `${differenceMinutes} minutes`;
  }

  const differenceHours = Math.floor(
    differenceMinutes / 60,
  );

  if (differenceHours < 24) {
    return differenceHours === 1
      ? "1 hour"
      : `${differenceHours} hours`;
  }

  const differenceDays = Math.floor(
    differenceHours / 24,
  );

  return differenceDays === 1
    ? "1 day"
    : `${differenceDays} days`;
}

/**
 * Replaces supported template variables.
 *
 * Supported:
 * - {city}
 * - {time}
 * - {minutes}, retained for backwards compatibility
 * - {product}
 */
function applyTemplate(template, values) {
  return String(template || "")
    .replaceAll(
      "{city}",
      values.city || "your area",
    )
    .replaceAll(
      "{time}",
      values.time || "recently",
    )
    .replaceAll(
      "{minutes}",
      values.time || "recently",
    )
    .replaceAll(
      "{product}",
      values.product || "this product",
    );
}

/**
 * Calculates distance between two coordinate pairs using the
 * Haversine formula.
 */
function calculateDistanceKm(
  firstLatitude,
  firstLongitude,
  secondLatitude,
  secondLongitude,
) {
  const latitude1 = toFiniteNumber(firstLatitude);
  const longitude1 = toFiniteNumber(firstLongitude);
  const latitude2 = toFiniteNumber(secondLatitude);
  const longitude2 = toFiniteNumber(secondLongitude);

  if (
    latitude1 === null ||
    longitude1 === null ||
    latitude2 === null ||
    longitude2 === null
  ) {
    return null;
  }

  const earthRadiusKm = 6371;

  const latitudeDifference =
    ((latitude2 - latitude1) * Math.PI) / 180;

  const longitudeDifference =
    ((longitude2 - longitude1) * Math.PI) / 180;

  const firstLatitudeRadians =
    (latitude1 * Math.PI) / 180;

  const secondLatitudeRadians =
    (latitude2 * Math.PI) / 180;

  const haversineValue =
    Math.sin(latitudeDifference / 2) ** 2 +
    Math.cos(firstLatitudeRadians) *
      Math.cos(secondLatitudeRadians) *
      Math.sin(longitudeDifference / 2) ** 2;

  const angularDistance =
    2 *
    Math.atan2(
      Math.sqrt(haversineValue),
      Math.sqrt(1 - haversineValue),
    );

  return earthRadiusKm * angularDistance;
}

/**
 * Determines whether an activity is near the current visitor.
 *
 * Coordinates are preferred.
 * If coordinates are unavailable, same-city matching is used.
 */
function isActivityNearby(
  activity,
  visitor,
  radiusKm,
) {
  const distance = calculateDistanceKm(
    visitor.latitude,
    visitor.longitude,
    activity.latitude,
    activity.longitude,
  );

  if (distance !== null) {
    return distance <= radiusKm;
  }

  const activityCity = cleanString(
    activity.visitor_city,
    150,
  )?.toLowerCase();

  const visitorCity = cleanString(
    visitor.city,
    150,
  )?.toLowerCase();

  if (!activityCity || !visitorCity) {
    return false;
  }

  return activityCity === visitorCity;
}

/**
 * Selects the most useful genuine activity.
 *
 * Priority:
 * 1. Completed order
 * 2. Checkout started
 * 3. Added to cart
 * 4. Product viewed
 *
 * Within the same event type, the newest activity wins.
 */
function selectBestActivity(activities) {
  if (
    !Array.isArray(activities) ||
    activities.length === 0
  ) {
    return null;
  }

  return [...activities].sort(
    (firstActivity, secondActivity) => {
      const priorityDifference =
        (ACTIVITY_PRIORITY[
          secondActivity.event_type
        ] || 0) -
        (ACTIVITY_PRIORITY[
          firstActivity.event_type
        ] || 0);

      if (priorityDifference !== 0) {
        return priorityDifference;
      }

      return (
        new Date(
          secondActivity.created_at,
        ).getTime() -
        new Date(
          firstActivity.created_at,
        ).getTime()
      );
    },
  )[0];
}

/**
 * Loads recent activity candidates for the current product.
 */
async function loadProductActivities({
  shop,
  productId,
  visitor,
  radiusKm,
}) {
  const thirtyDaysAgo = new Date(
    Date.now() -
      30 * 24 * 60 * 60 * 1000,
  ).toISOString();

  const { data, error } = await supabase
    .from("storefront_activities")
    .select(
      `
        id,
        event_type,
        product_id,
        product_title,
        visitor_city,
        visitor_country,
        latitude,
        longitude,
        source,
        created_at
      `,
    )
    .eq("shop", shop)
    .eq("product_id", productId)
    .in(
      "event_type",
      ALLOWED_ACTIVITY_EVENT_TYPES,
    )
    .gte("created_at", thirtyDaysAgo)
    .order("created_at", {
      ascending: false,
    })
    .limit(100);

  if (error) {
    console.error(
      "Unable to load storefront activities:",
      error,
    );

    return [];
  }

  return (data || []).filter((activity) =>
    isActivityNearby(
      activity,
      visitor,
      radiusKm,
    ),
  );
}

/**
 * Loads the merchant templates for one activity type.
 */
async function loadActivityTemplates(
  shop,
  eventType,
) {
  const { data, error } = await supabase
    .from("message_templates")
    .select(
      `
        template,
        event_type,
        is_announcement,
        is_enabled,
        sort_order
      `,
    )
    .eq("shop", shop)
    .eq("event_type", eventType)
    .eq("is_announcement", false)
    .eq("is_enabled", true)
    .order("sort_order", {
      ascending: true,
    });

  if (error) {
    console.error(
      `Unable to load ${eventType} templates:`,
      error,
    );

    return [];
  }

  return (data || [])
    .map((item) =>
      cleanString(item.template, 500),
    )
    .filter(Boolean);
}

/**
 * Loads all active merchant announcements.
 */
async function loadAnnouncements(shop) {
  const { data, error } = await supabase
    .from("message_templates")
    .select(
      `
        template,
        event_type,
        is_announcement,
        is_enabled,
        sort_order
      `,
    )
    .eq("shop", shop)
    .eq("event_type", "announcement")
    .eq("is_announcement", true)
    .eq("is_enabled", true)
    .order("sort_order", {
      ascending: true,
    });

  if (error) {
    console.error(
      "Unable to load merchant announcements:",
      error,
    );

    return [];
  }

  return (data || [])
    .map((item) =>
      cleanString(item.template, 500),
    )
    .filter(Boolean);
}

/**
 * Selects a merchant template according to the saved message mode.
 */
function selectTemplate(
  templates,
  messageMode,
) {
  if (
    !Array.isArray(templates) ||
    templates.length === 0
  ) {
    return null;
  }

  if (messageMode === "first") {
    return templates[0];
  }

  return getRandomItem(templates);
}

/**
 * Determines which city should be displayed.
 *
 * activity:
 *   Uses the city saved with the genuine activity.
 *
 * nearest:
 *   Uses a nearby city returned by the nearby_cities Supabase RPC.
 */
async function resolveDisplayedCity({
  settings,
  visitor,
  activity,
}) {
  const activityCity = cleanString(
    activity?.visitor_city,
    150,
  );

  if (
    settings.city_mode !== "nearest"
  ) {
    return (
      activityCity ||
      cleanString(visitor.city, 150) ||
      "your area"
    );
  }

  const latitude = toFiniteNumber(
    visitor.latitude,
  );

  const longitude = toFiniteNumber(
    visitor.longitude,
  );

  if (
    latitude === null ||
    longitude === null
  ) {
    return (
      activityCity ||
      cleanString(visitor.city, 150) ||
      "your area"
    );
  }

  const radiusKm = clampNumber(
    settings.radius_km,
    1,
    1000,
    100,
  );

  const { data, error } = await supabase.rpc(
    "nearby_cities",
    {
      input_lat: latitude,
      input_lng: longitude,
      radius_meters: radiusKm * 1000,
    },
  );

  if (
    error ||
    !Array.isArray(data) ||
    data.length === 0
  ) {
    if (error) {
      console.error(
        "Unable to load nearest matching city:",
        error,
      );
    }

    return (
      activityCity ||
      cleanString(visitor.city, 150) ||
      "your area"
    );
  }

  /**
   * Prefer a city that matches the genuine activity city.
   */
  if (activityCity) {
    const matchingCity = data.find(
      (city) =>
        cleanString(
          city.name,
          150,
        )?.toLowerCase() ===
        activityCity.toLowerCase(),
    );

    if (matchingCity?.name) {
      return matchingCity.name;
    }
  }

  /**
   * The RPC should return cities ordered by distance.
   */
  return (
    cleanString(data[0]?.name, 150) ||
    activityCity ||
    cleanString(visitor.city, 150) ||
    "your area"
  );
}

/**
 * Builds a genuine activity-backed message.
 */
async function buildActivityMessage({
  shop,
  settings,
  activity,
  visitor,
  productTitle,
}) {
  if (!activity) {
    return null;
  }

  const eventType = activity.event_type;

  if (
    !ALLOWED_ACTIVITY_EVENT_TYPES.includes(
      eventType,
    )
  ) {
    return null;
  }

  let templates =
    await loadActivityTemplates(
      shop,
      eventType,
    );

  if (templates.length === 0) {
    templates =
      DEFAULT_TEMPLATES[eventType] || [];
  }

  const selectedTemplate = selectTemplate(
    templates,
    settings.message_mode,
  );

  if (!selectedTemplate) {
    return null;
  }

  const displayedCity =
    await resolveDisplayedCity({
      settings,
      visitor,
      activity,
    });

  const message = applyTemplate(
    selectedTemplate,
    {
      city: displayedCity,
      time: formatTimeSince(
        activity.created_at,
      ),
      product:
        cleanString(
          activity.product_title,
          255,
        ) ||
        productTitle ||
        "this product",
    },
  );

  return {
    message,
    messageType: eventType,
    displayedCity,
    sourceActivityId: activity.id,
    sourceActivityType: eventType,
  };
}

/**
 * Builds a merchant announcement.
 *
 * Announcements must not be presented as genuine customer activity.
 */

function buildAnnouncementMessage({
  announcements,
  settings,
}) {
  const safeAnnouncements = announcements.filter(
    (message) => !/{[^}]+}/.test(String(message || "")),
  );

  const selectedMessage = selectTemplate(
    safeAnnouncements,
    settings.message_mode,
  );

  if (!selectedMessage) {
    return null;
  }

  return {
    message: selectedMessage,
    messageType: "announcement",
    displayedCity: null,
    sourceActivityId: null,
    sourceActivityType: null,
  };
}
/**
 * GET /api/nearby-activity
 *
 * Called by the storefront theme extension through the Shopify app proxy.
 */
export async function loader({ request }) {
  let shop;

  try {
    const proxy =
      await authenticate.public.appProxy(
        request,
      );

    shop = proxy.session?.shop;
  } catch (error) {
    console.error(
      "Nearby activity app-proxy authentication failed:",
      error,
    );

    return Response.json(
      DEFAULT_RESPONSE,
      {
        status: 401,
      },
    );
  }

  if (!shop) {
    return Response.json(
      DEFAULT_RESPONSE,
    );
  }

  const requestUrl = new URL(
    request.url,
  );

  const productId = normaliseProductId(
    requestUrl.searchParams.get(
      "product_id",
    ),
  );

  const productTitle = cleanString(
    requestUrl.searchParams.get(
      "product_title",
    ),
    255,
  );

  if (!productId) {
    return Response.json(
      DEFAULT_RESPONSE,
    );
  }

  const {
    data: settings,
    error: settingsError,
  } = await supabase
    .from("shop_settings")
    .select("*")
    .eq("shop", shop)
    .maybeSingle();

  if (
    settingsError ||
    !settings ||
    settings.is_enabled !== true
  ) {
    if (settingsError) {
      console.error(
        "Unable to load shop settings:",
        settingsError,
      );
    }

    return Response.json(
      DEFAULT_RESPONSE,
    );
  }

  const clientIp =
    getClientIp(request);

  let visitor;

  try {
    visitor =
      await getLocationFromIp(
        clientIp,
      );
  } catch (error) {
    console.error(
      "Unable to resolve visitor location:",
      error,
    );

    return Response.json(
      DEFAULT_RESPONSE,
    );
  }

  const visitorLatitude =
    toFiniteNumber(visitor?.latitude);

  const visitorLongitude =
    toFiniteNumber(visitor?.longitude);

  if (
    !visitor ||
    visitorLatitude === null ||
    visitorLongitude === null
  ) {
    return Response.json(
      DEFAULT_RESPONSE,
    );
  }

  const radiusKm = clampNumber(
    settings.radius_km,
    1,
    1000,
    100,
  );

  const activities =
    await loadProductActivities({
      shop,
      productId,
      visitor: {
        ...visitor,
        latitude: visitorLatitude,
        longitude: visitorLongitude,
      },
      radiusKm,
    });

  const selectedActivity =
    selectBestActivity(activities);

  const announcements =
    await loadAnnouncements(shop);

  const announcementPercentage =
    clampNumber(
      settings.announcement_percentage,
      0,
      100,
      20,
    );

  /**
   * When genuine activity exists:
   * - Announcements appear according to announcement_percentage.
   * - Otherwise, the activity-backed message appears.
   *
   * When no activity exists:
   * - A merchant announcement may still appear.
   * - No fake activity message is generated.
   */
  const shouldPreferAnnouncement =
    announcements.length > 0 &&
    Math.random() * 100 <
      announcementPercentage;

  let selectedMessage = null;

  if (shouldPreferAnnouncement) {
    selectedMessage =
      buildAnnouncementMessage({
        announcements,
        settings,
        visitor,
        productTitle,
      });
  }

  if (
    !selectedMessage &&
    selectedActivity
  ) {
    selectedMessage =
      await buildActivityMessage({
        shop,
        settings,
        activity: selectedActivity,
        visitor,
        productTitle,
      });
  }

  if (
    !selectedMessage &&
    announcements.length > 0
  ) {
    selectedMessage =
      buildAnnouncementMessage({
        announcements,
        settings,
        visitor,
        productTitle,
      });
  }

  if (
    !selectedMessage ||
    !selectedMessage.message
  ) {
    return Response.json(
      DEFAULT_RESPONSE,
    );
  }

  return Response.json({
    shouldShow: true,

    message:
      selectedMessage.message,

    messageType:
      selectedMessage.messageType,

    tracking: {
      productId,
      productTitle,

      visitorCity:
        cleanString(
          visitor.city,
          150,
        ),

      visitorCountry:
        cleanString(
          visitor.countryCode,
          10,
        ),

      displayedCity:
        selectedMessage.displayedCity,

      messageText:
        selectedMessage.message,

      messageType:
        selectedMessage.messageType,

      sourceActivityId:
        selectedMessage.sourceActivityId,

      sourceActivityType:
        selectedMessage.sourceActivityType,
    },

    displaySeconds:
      clampNumber(
        settings.display_seconds,
        3,
        30,
        10,
      ),

    cooldownMinutes:
      clampNumber(
        settings.cooldown_minutes,
        0,
        180,
        15,
      ),

    maxPerProductPerHour:
      clampNumber(
        settings.max_per_product_per_hour,
        1,
        20,
        3,
      ),
  });
}

/**
 * POST /api/nearby-activity
 *
 * Records widget analytics.
 *
 * This does not record genuine storefront activity. Genuine storefront
 * events should be posted to api.track-event.js or recorded through a
 * trusted Shopify webhook/Web Pixel integration.
 */
export async function action({ request }) {
  let shop;

  try {
    const proxy =
      await authenticate.public.appProxy(
        request,
      );

    shop = proxy.session?.shop;
  } catch (error) {
    console.error(
      "NearbyPulse analytics authentication failed:",
      error,
    );

    return Response.json(
      {
        success: false,
        error: "Unauthorized",
      },
      {
        status: 401,
      },
    );
  }

  if (!shop) {
    return Response.json(
      {
        success: false,
        error: "Missing shop",
      },
      {
        status: 400,
      },
    );
  }

  let body;

  try {
    body = await request.json();
  } catch {
    return Response.json(
      {
        success: false,
        error: "Invalid JSON body",
      },
      {
        status: 400,
      },
    );
  }

  const eventType =
    cleanString(
      body.event_type,
      50,
    );

  if (
    !eventType ||
    !ALLOWED_ANALYTICS_EVENT_TYPES.has(
      eventType,
    )
  ) {
    return Response.json(
      {
        success: false,
        error: "Invalid analytics event type",
      },
      {
        status: 400,
      },
    );
  }

  const analyticsRow = {
    shop,

    event_type: eventType,

    product_id: normaliseProductId(
      body.productId,
    ),

    product_title: cleanString(
      body.productTitle,
      255,
    ),

    visitor_city: cleanString(
      body.visitorCity,
      150,
    ),

    visitor_country: cleanString(
      body.visitorCountry,
      10,
    ),

    displayed_city: cleanString(
      body.displayedCity,
      150,
    ),

    message_text: cleanString(
      body.messageText,
      500,
    ),
  };

  const { error } = await supabase
    .from("analytics_events")
    .insert(analyticsRow);

  if (error) {
    console.error(
      "Unable to save NearbyPulse analytics event:",
      error,
    );

    return Response.json(
      {
        success: false,
        error:
          "Unable to record analytics event",
      },
      {
        status: 500,
      },
    );
  }

  return Response.json({
    success: true,
  });
}
